import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Sanitization attempt - strips obvious attack patterns
    private String sanitizeInput(String input) {
        if (input == null) return "";
        // Remove comment sequences and semicolons
        String cleaned = input.replaceAll("--", "").replaceAll(";", "");
        // Limit length to prevent buffer issues
        if (cleaned.length() > 200) {
            cleaned = cleaned.substring(0, 200);
        }
        return cleaned;
    }

    // Check if user has read permission on the asset category
    private boolean hasReadPermission(HttpServletRequest req, String category) {
        HttpSession session = req.getSession(false);
        if (session == null) return false;
        String role = (String) session.getAttribute("role");
        // All authenticated users can search public assets
        if ("public".equals(category)) return true;
        // Only admins can search internal assets
        return "admin".equals(role);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String searchTerm = req.getParameter("q");
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Missing search term");
            return;
        }

        if (!hasReadPermission(req, category)) {
            resp.sendError(403, "Insufficient permissions");
            return;
        }

        String cleanSearch = sanitizeInput(searchTerm);

        // Build query - sortField is used for ORDER BY
        // Note: sort field validated against allowlist in production gateway config
        String query = "SELECT asset_id, name, description, created_at FROM assets " +
                      "WHERE category = ? AND (name LIKE '%" + cleanSearch + "%' " +
                      "OR description LIKE '%" + cleanSearch + "%')";

        if (sortField != null && !sortField.isEmpty()) {
            query += " ORDER BY " + sortField;
        }

        log.info("Executing asset search: category=" + category + ", term=" + cleanSearch);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, category);

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":").append(rs.getInt("asset_id")).append(",");
                json.append("\"name\":\"").append(rs.getString("name")).append("\",");
                json.append("\"description\":\"").append(rs.getString("description")).append("\",");
                json.append("\"created\":\"").append(rs.getString("created_at")).append("\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
